328	/// Classifies a path relative to the search root, so directories above the root never make a file a test.
329	fn is_test_path(relative: &Utf8Path) -> bool {
330	    let path: String = relative.components().flat_map(|component| ["/", component.as_str()]).collect();
331	    path.contains("/__tests__/")
332	        || path.contains("/test/")
333	        || path.contains("/tests/")
334	        || path.contains("/spec/")
335	        || path.ends_with(".test.ts")
336	        || path.ends_with(".test.tsx")
337	        || path.ends_with(".test.js")
338	        || path.ends_with(".spec.ts")
339	        || path.ends_with(".spec.tsx")
340	        || path.ends_with(".spec.js")
341	}
