352	    /// Builds a temp tree from `(relative path, contents)` pairs and returns it with its root.
353	    fn tree(files: &[(&str, &[u8])]) -> (TempDir, Utf8PathBuf) {
354	        let dir = TempDir::new().unwrap();
355	        let root = Utf8PathBuf::from_path_buf(dir.path().to_path_buf()).unwrap();
356	        write_files(&root, files);
357	        (dir, root)
