360	    fn write_files(root: &Utf8Path, files: &[(&str, &[u8])]) {
361	        for (relative, contents) in files {
362	            let path = root.join(relative);
363	            fs::create_dir_all(path.parent().unwrap()).unwrap();
364	            fs::write(&path, contents).unwrap();
365	        }
366	    }
