1	//! The core of `monokl search`: a query in, fully ranked and deduplicated blocks out.
2	//!
3	//! Nothing here caps, budgets, serializes or prints. Callers get every surviving block with the counts needed to
4	//! describe what was left out, and apply their own budget.
5	
6	use std::collections::BTreeSet;
7	use std::io;
8	
9	use camino::{Utf8Path, Utf8PathBuf};
10	use grep_matcher::Matcher;
11	use grep_regex::{RegexMatcher, RegexMatcherBuilder};
12	use rustc_hash::{FxHashMap, FxHashSet};
13	
14	use crate::analysis::LanguageId;
15	use crate::analysis::registry::AnalyzerRegistry;
16	use crate::dedup::dedup_blocks;
17	use crate::error::{MonoklError, Result};
18	use crate::file_io::FileIoError;
19	use crate::query::{Modifier, ParsedTerm, QueryPlan, parse};
20	use crate::rank::{rank_blocks, tokenize_block};
21	use crate::text_search::{DEFAULT_MAX_FILES, TextSearchOptions, TextSearchResult, search_files};
22	use crate::tokens::tokenize;
23	use crate::types::{CodeBlock, Diagnostic, DiagnosticKind, Language, LineHit, RankedBlock};
24	
25	/// What to search for and where.
26	#[derive(Clone, Copy, Debug)]
27	pub struct SearchRequest<'a> {
28	    /// The directory to search; it is canonicalized first.
29	    pub root: &'a Utf8Path,
30	    /// The query text, in the syntax [`parse`] reads, or a literal when `exact` is set.
31	    pub query: &'a str,
32	    /// Treats the whole query as one literal term, operators and quotes included.
33	    pub exact: bool,
34	    /// Searches test files too.
35	    pub allow_tests: bool,
36	    /// Skips hidden files and what `.gitignore` and `.ignore` files inside the root exclude.
37	    pub respect_ignore_files: bool,
38	    /// Restricts the search to one language; only TypeScript and JavaScript are supported.
39	    pub language: Option<Language>,
40	}
41	
42	/// Everything a search found, best first and uncapped.
43	#[derive(Clone, Debug)]
44	pub struct SearchResult {
45	    /// Deduplicated blocks with 1-based, contiguous ranks.
46	    pub ranked: Vec<RankedBlock>,
47	    /// Files with at least one line matching a positive term, kept or not.
48	    pub files_total: u64,
49	    /// Whether `files_total` exceeded the file ceiling, so some matching files were never examined.
50	    pub ceiling_hit: bool,
51	    /// What was skipped or only partly understood, in a deterministic order.
52	    pub diagnostics: Vec<Diagnostic>,
53	}
54	
55	impl SearchResult {
56	    fn empty() -> Self {
57	        Self { ranked: Vec::new(), files_total: 0, ceiling_hit: false, diagnostics: Vec::new() }
58	    }
59	
60	    fn skipped(message: impl Into<String>) -> Self {
61	        Self { diagnostics: vec![skipped(None, message)], ..Self::empty() }
62	    }
63	}
64	
65	/// Runs a search over `request.root` and returns ranked blocks.
66	///
67	/// Text search finds the lines matching the query's positive terms; files with a line matching an excluded term, or
68	/// lacking a match for a required term, drop out. Each remaining file goes to the analyzer that owns it, and only
69	/// blocks containing a matching line are kept, ranked with BM25 and deduplicated. Files no analyzer supports are
70	/// ignored without a diagnostic.
71	///
72	/// BM25 query terms are the lowercase [`tokenize`] output of each non-excluded literal term. Regex terms select
73	/// lines and appear in `matched_keywords` but add no BM25 terms. A query with only excluded terms has nothing to
74	/// search for and returns an empty result with one `Skipped` diagnostic.
75	///
76	/// # Errors
77	///
78	/// - [`MonoklError::TooManyTerms`] if the query has too many terms.
79	/// - [`MonoklError::RegexBuild`] if any term is not a valid regex; no file is read first.
80	/// - [`MonoklError::Io`] or [`MonoklError::NonUtf8Path`] if `request.root` cannot be canonicalized.
81	/// - [`MonoklError::Walk`] if the root is not a listable directory.
82	///
83	/// # Examples
84	///
85	/// ```
86	/// use camino::Utf8Path;
87	/// use monokl::analysis::registry::AnalyzerRegistry;
88	/// use monokl::pipeline::{SearchRequest, search};
89	///
90	/// let dir = tempfile::tempdir()?;
91	/// std::fs::write(dir.path().join("a.ts"), "const alpha = 1;\n")?;
92	/// let root = Utf8Path::from_path(dir.path()).ok_or("temp dir is not UTF-8")?;
93	/// let request = SearchRequest {
94	///     root,
95	///     query: "alpha",
96	///     exact: false,
97	///     allow_tests: false,
98	///     respect_ignore_files: true,
99	///     language: None,
100	/// };
101	///
102	/// // With no analyzer registered, the file matches but yields no blocks.
103	/// let result = search(&AnalyzerRegistry::new(Vec::new()), &request)?;
104	/// assert_eq!(result.files_total, 1);
105	/// assert!(result.ranked.is_empty());
106	/// # Ok::<(), Box<dyn std::error::Error>>(())
107	/// ```
108	pub fn search(registry: &AnalyzerRegistry, request: &SearchRequest<'_>) -> Result<SearchResult> {
109	    search_with_ceiling(registry, request, DEFAULT_MAX_FILES)
110	}
111	
112	/// [`search`] with the file ceiling as a parameter, so tests can reach it without 100,000 files.
113	fn search_with_ceiling(
114	    registry: &AnalyzerRegistry,
115	    request: &SearchRequest<'_>,
116	    max_files: usize,
117	) -> Result<SearchResult> {
118	    let SearchRequest { root, query, exact, allow_tests, respect_ignore_files, language } = *request;
119	    if let Some(language) = language
120	        && !is_supported(language)
121	    {
122	        return Ok(SearchResult::skipped(format!(
123	            "language {language:?} not supported in v1; only TypeScript/JavaScript"
124	        )));
125	    }
126	
127	    let terms = if exact {
128	        if query.trim().is_empty() {
129	            Vec::new()
130	        } else {
131	            vec![ParsedTerm { modifier: Modifier::Optional, pattern: regex::escape(query), is_regex: false }]
132	        }
133	    } else {
134	        parse(query)?
135	    };
136	    let plan = QueryPlan::from_terms(terms);
137	    if plan.is_empty() {
138	        return Ok(SearchResult::empty());
139	    }
140	    let patterns = plan.search_patterns();
141	    if patterns.is_empty() {
142	        return Ok(SearchResult::skipped("query has no positive terms; add a term without a leading `-`"));
143	    }
144	
145	    // Every term, excluded ones too, compiles before any file is read, so an invalid one fails the whole query.
146	    let matchers = plan.terms.iter().map(|term| compile(&term.pattern)).collect::<Result<Vec<_>>>()?;
147	    let root = canonicalize(root)?;
148	
149	    let found = search_files(&root, &patterns, &TextSearchOptions { allow_tests, respect_ignore_files, max_files })?;
150	    let mut diagnostics = text_search_diagnostics(&found);
151	
152	    // The ceiling must not apply here: an excluded file past it would wrongly survive.
153	    let excluded_files = if found.hits.is_empty() || plan.excluded.is_empty() {
154	        BTreeSet::new()
155	    } else {
156	        let excluded_patterns: Vec<&str> = plan.excluded.iter().map(|&i| plan.terms[i].pattern.as_str()).collect();
157	        let excluded = search_files(
158	            &root,
159	            &excluded_patterns,
160	            &TextSearchOptions { allow_tests, respect_ignore_files, max_files: usize::MAX },
161	        )?;
162	        // The walk is the same, so only a file unreadable for the excluded patterns alone is new.
163	        for path in &excluded.unreadable {
164	            if !found.unreadable.contains(path) {
165	                diagnostics.push(unreadable_diagnostic(path));
166	            }
167	        }
168	        excluded.hits.into_keys().collect()
169	    };
170	
171	    let mut candidates: Vec<(CodeBlock, Vec<String>)> = Vec::new();
172	    for (path, hits) in &found.hits {
173	        if excluded_files.contains(path) {
174	            continue;
175	        }
176	        let has_every_required =
177	            plan.required.iter().all(|&i| hits.iter().any(|hit| matches_text(&matchers[i], &hit.text)));
178	        if !has_every_required {
179	            continue;
180	        }
181	        let ctx = FileContext { registry, plan: &plan, matchers: &matchers, language };
182	        retrieve_blocks(&ctx, path, hits, &read_source, &mut candidates, &mut diagnostics);
183	    }
184	
185	    let bm25_terms = bm25_terms(&plan);
186	    let df = document_frequencies(&candidates, &bm25_terms);
187	    let bm25_terms: Vec<&str> = bm25_terms.iter().map(String::as_str).collect();
188	    let ranked = dedup_blocks(rank_blocks(candidates, &bm25_terms, &df));
189	
190	    Ok(SearchResult { ranked, files_total: found.files_total, ceiling_hit: found.ceiling_hit, diagnostics })
191	}
192	
193	/// Returns whether `language` has an analyzer path in v1.
194	fn is_supported(language: Language) -> bool {
195	    match language {
196	        Language::TypeScript | Language::JavaScript => true,
197	        Language::Rust | Language::Python => false,
198	    }
199	}
200	
201	/// Compiles one term the way text search does, case-insensitively, so a term can never match differently here.
202	fn compile(pattern: &str) -> Result<RegexMatcher> {
203	    Ok(RegexMatcherBuilder::new().case_insensitive(true).build(pattern)?)
204	}
205	
206	fn canonicalize(root: &Utf8Path) -> Result<Utf8PathBuf> {
207	    let path = root.as_std_path().canonicalize().map_err(|source| FileIoError::read(root, source))?;
208	    Utf8PathBuf::from_path_buf(path).map_err(|path| MonoklError::NonUtf8Path { path })
209	}
210	
211	fn read_source(path: &Utf8Path) -> io::Result<String> {
212	    std::fs::read_to_string(path)
213	}
214	
215	/// Whether `matcher` matches `text`. Matching in memory cannot fail, so an error counts as no match.
216	fn matches_text(matcher: &RegexMatcher, text: &str) -> bool {
217	    matches!(matcher.is_match(text.as_bytes()), Ok(true))
218	}
219	
220	fn skipped(path: Option<&Utf8Path>, message: impl Into<String>) -> Diagnostic {
221	    Diagnostic { kind: DiagnosticKind::Skipped, path: path.map(Utf8Path::to_owned), message: message.into() }
222	}
223	
224	fn unreadable_diagnostic(path: &Utf8Path) -> Diagnostic {
225	    skipped(Some(path), "file could not be read, or a matching line is not UTF-8")
226	}
227	
228	/// Turns what text search could not read into diagnostics: one per unreadable path, then one per non-zero count.
229	fn text_search_diagnostics(found: &TextSearchResult) -> Vec<Diagnostic> {
230	    let mut diagnostics: Vec<Diagnostic> = found.unreadable.iter().map(|path| unreadable_diagnostic(path)).collect();
231	    if found.non_utf8_paths > 0 {
232	        diagnostics.push(skipped(None, format!("{} files skipped: path is not valid UTF-8", found.non_utf8_paths)));
233	    }
234	    if found.walk_errors_without_path > 0 {
235	        diagnostics.push(skipped(
236	            None,
