212	/// How searching one file ended.
213	enum FileOutcome {
214	    Binary,
215	    Unreadable,
216	    /// The file's matching lines, possibly none.
217	    Lines(Vec<LineHit>),
218	}
219	
220	fn search_file(searcher: &mut Searcher, matcher: &RegexMatcher, path: &Utf8Path) -> FileOutcome {
221	    let mut sink = LineCollector::new(matcher);
222	    match searcher.search_path(matcher, path.as_std_path(), &mut sink) {
223	        Err(_) => FileOutcome::Unreadable,
224	        Ok(()) if sink.binary => FileOutcome::Binary,
225	        Ok(()) if sink.not_utf8 => FileOutcome::Unreadable,
226	        Ok(()) => FileOutcome::Lines(sink.hits),
227	    }
228	}
229	
230	/// Collects matching lines, and stops at the first sign of binary data so the caller can discard the whole file,
231	/// including lines matched before the NUL byte was reached. A matching line that is not UTF-8 does not stop the
232	/// search, so a NUL later in the file still marks it binary.
233	///
234	/// The searcher strips only the `\n` before matching, so a line ending in `\r\n` is matched again here against its
235	/// text without the terminator: a pattern always sees exactly the text a hit reports.
236	struct LineCollector<'m> {
237	    matcher: &'m RegexMatcher,
238	    /// Matches one CRLF line's text, which holds no `\n`, so it searches it as a single line.
239	    line_searcher: Searcher,
240	    /// Reused to hold the text [`Self::line_searcher`] searches.
241	    line_buf: Vec<u8>,
242	    hits: Vec<LineHit>,
243	    binary: bool,
244	    not_utf8: bool,
245	}
246	
247	impl<'m> LineCollector<'m> {
248	    fn new(matcher: &'m RegexMatcher) -> Self {
249	        Self {
250	            matcher,
251	            line_searcher: SearcherBuilder::new().bom_sniffing(false).build(),
252	            line_buf: Vec::new(),
253	            hits: Vec::new(),
254	            binary: false,
255	            not_utf8: false,
256	        }
257	    }
258	
259	    /// Records `line` as a hit when it matches. `searcher_matched` is the searcher's verdict, which is final unless the
260	    /// line ends in `\r\n`.
261	    fn line(&mut self, line_number: Option<u64>, line: &[u8], searcher_matched: bool) -> io::Result<()> {
262	        let text = without_line_terminator(line);
263	        let matched = if line.ends_with(b"\r\n") { self.text_matches(text)? } else { searcher_matched };
264	        if !matched {
265	            return Ok(());
266	        }
267	        let line_number = line_number
268	            .and_then(|line_number| usize::try_from(line_number).ok())
269	            .ok_or_else(|| io::Error::other("matched line has no usable line number"))?;
270	        match std::str::from_utf8(text) {
271	            Ok(text) => self.hits.push(LineHit { line_number, text: text.to_owned() }),
272	            Err(_) => self.not_utf8 = true,
273	        }
274	        Ok(())
275	    }
276	
277	    fn text_matches(&mut self, text: &[u8]) -> io::Result<bool> {
278	        // An empty slice has no lines to match, so the text is searched as one `\n`-terminated line, which the
279	        // searcher strips again before matching.
280	        self.line_buf.clear();
281	        self.line_buf.extend_from_slice(text);
282	        self.line_buf.push(b'\n');
283	        let mut found = AnyMatch(false);
284	        self.line_searcher.search_slice(self.matcher, &self.line_buf, &mut found)?;
285	        Ok(found.0)
286	    }
287	}
288	
289	impl Sink for LineCollector<'_> {
290	    type Error = io::Error;
291	
292	    fn matched(&mut self, _searcher: &Searcher, mat: &SinkMatch<'_>) -> io::Result<bool> {
293	        self.line(mat.line_number(), mat.bytes(), true)?;
294	        Ok(true)
295	    }
296	
297	    fn context(&mut self, _searcher: &Searcher, context: &SinkContext<'_>) -> io::Result<bool> {
