320	/// Strips one trailing `\n` or `\r\n`. A `\r` not followed by `\n` is line content and stays.
321	fn without_line_terminator(line: &[u8]) -> &[u8] {
322	    match line.strip_suffix(b"\n") {
323	        Some(line) => line.strip_suffix(b"\r").unwrap_or(line),
324	        None => line,
325	    }
