25	/// What to search for and where.
26	#[derive(Clone, Copy, Debug)]
27	pub struct SearchRequest<'a> {
28	    /// The directory to search; it is canonicalized first.
29	    pub root: &'a Utf8Path,
30	    /// The query text, in the syntax [`parse`] reads, or a literal when `exact` is set.
31	    pub query: &'a str,
32	    /// Treats the whole query as one literal term, operators and quotes included.
33	    pub exact: bool,
34	    /// Searches test files too.
35	    pub allow_tests: bool,
36	    /// Skips hidden files and what `.gitignore` and `.ignore` files inside the root exclude.
37	    pub respect_ignore_files: bool,
38	    /// Restricts the search to one language; only TypeScript and JavaScript are supported.
39	    pub language: Option<Language>,
40	}
