65	/// Runs a search over `request.root` and returns ranked blocks.
66	///
67	/// Text search finds the lines matching the query's positive terms; files with a line matching an excluded term, or
68	/// lacking a match for a required term, drop out. Each remaining file goes to the analyzer that owns it, and only
69	/// blocks containing a matching line are kept, ranked with BM25 and deduplicated. Files no analyzer supports are
70	/// ignored without a diagnostic.
71	///
72	/// BM25 query terms are the lowercase [`tokenize`] output of each non-excluded literal term. Regex terms select
73	/// lines and appear in `matched_keywords` but add no BM25 terms. A query with only excluded terms has nothing to
74	/// search for and returns an empty result with one `Skipped` diagnostic.
75	///
76	/// # Errors
77	///
78	/// - [`MonoklError::TooManyTerms`] if the query has too many terms.
79	/// - [`MonoklError::RegexBuild`] if any term is not a valid regex; no file is read first.
80	/// - [`MonoklError::Io`] or [`MonoklError::NonUtf8Path`] if `request.root` cannot be canonicalized.
81	/// - [`MonoklError::Walk`] if the root is not a listable directory.
82	///
83	/// # Examples
84	///
85	/// ```
86	/// use camino::Utf8Path;
87	/// use monokl::analysis::registry::AnalyzerRegistry;
88	/// use monokl::pipeline::{SearchRequest, search};
89	///
90	/// let dir = tempfile::tempdir()?;
91	/// std::fs::write(dir.path().join("a.ts"), "const alpha = 1;\n")?;
92	/// let root = Utf8Path::from_path(dir.path()).ok_or("temp dir is not UTF-8")?;
93	/// let request = SearchRequest {
94	///     root,
95	///     query: "alpha",
96	///     exact: false,
97	///     allow_tests: false,
98	///     respect_ignore_files: true,
99	///     language: None,
100	/// };
101	///
102	/// // With no analyzer registered, the file matches but yields no blocks.
103	/// let result = search(&AnalyzerRegistry::new(Vec::new()), &request)?;
104	/// assert_eq!(result.files_total, 1);
105	/// assert!(result.ranked.is_empty());
106	/// # Ok::<(), Box<dyn std::error::Error>>(())
107	/// ```
108	pub fn search(registry: &AnalyzerRegistry, request: &SearchRequest<'_>) -> Result<SearchResult> {
109	    search_with_ceiling(registry, request, DEFAULT_MAX_FILES)
110	}
111	
112	/// [`search`] with the file ceiling as a parameter, so tests can reach it without 100,000 files.
113	fn search_with_ceiling(
114	    registry: &AnalyzerRegistry,
115	    request: &SearchRequest<'_>,
116	    max_files: usize,
117	) -> Result<SearchResult> {
118	    let SearchRequest { root, query, exact, allow_tests, respect_ignore_files, language } = *request;
119	    if let Some(language) = language
120	        && !is_supported(language)
121	    {
122	        return Ok(SearchResult::skipped(format!(
123	            "language {language:?} not supported in v1; only TypeScript/JavaScript"
124	        )));
125	    }
126	
127	    let terms = if exact {
128	        if query.trim().is_empty() {
129	            Vec::new()
130	        } else {
131	            vec![ParsedTerm { modifier: Modifier::Optional, pattern: regex::escape(query), is_regex: false }]
132	        }
133	    } else {
134	        parse(query)?
135	    };
136	    let plan = QueryPlan::from_terms(terms);
137	    if plan.is_empty() {
138	        return Ok(SearchResult::empty());
139	    }
140	    let patterns = plan.search_patterns();
141	    if patterns.is_empty() {
142	        return Ok(SearchResult::skipped("query has no positive terms; add a term without a leading `-`"));
143	    }
144	
145	    // Every term, excluded ones too, compiles before any file is read, so an invalid one fails the whole query.
146	    let matchers = plan.terms.iter().map(|term| compile(&term.pattern)).collect::<Result<Vec<_>>>()?;
147	    let root = canonicalize(root)?;
148	
149	    let found = search_files(&root, &patterns, &TextSearchOptions { allow_tests, respect_ignore_files, max_files })?;
150	    let mut diagnostics = text_search_diagnostics(&found);
151	
152	    // The ceiling must not apply here: an excluded file past it would wrongly survive.
153	    let excluded_files = if found.hits.is_empty() || plan.excluded.is_empty() {
154	        BTreeSet::new()
155	    } else {
156	        let excluded_patterns: Vec<&str> = plan.excluded.iter().map(|&i| plan.terms[i].pattern.as_str()).collect();
157	        let excluded = search_files(
158	            &root,
159	            &excluded_patterns,
160	            &TextSearchOptions { allow_tests, respect_ignore_files, max_files: usize::MAX },
161	        )?;
162	        // The walk is the same, so only a file unreadable for the excluded patterns alone is new.
163	        for path in &excluded.unreadable {
164	            if !found.unreadable.contains(path) {
165	                diagnostics.push(unreadable_diagnostic(path));
166	            }
167	        }
168	        excluded.hits.into_keys().collect()
169	    };
170	
171	    let mut candidates: Vec<(CodeBlock, Vec<String>)> = Vec::new();
172	    for (path, hits) in &found.hits {
173	        if excluded_files.contains(path) {
174	            continue;
175	        }
176	        let has_every_required =
177	            plan.required.iter().all(|&i| hits.iter().any(|hit| matches_text(&matchers[i], &hit.text)));
178	        if !has_every_required {
179	            continue;
180	        }
181	        let ctx = FileContext { registry, plan: &plan, matchers: &matchers, language };
182	        retrieve_blocks(&ctx, path, hits, &read_source, &mut candidates, &mut diagnostics);
183	    }
184	
185	    let bm25_terms = bm25_terms(&plan);
186	    let df = document_frequencies(&candidates, &bm25_terms);
187	    let bm25_terms: Vec<&str> = bm25_terms.iter().map(String::as_str).collect();
188	    let ranked = dedup_blocks(rank_blocks(candidates, &bm25_terms, &df));
189	
190	    Ok(SearchResult { ranked, files_total: found.files_total, ceiling_hit: found.ceiling_hit, diagnostics })
191	}
