193	/// Returns whether `language` has an analyzer path in v1.
194	fn is_supported(language: Language) -> bool {
195	    match language {
196	        Language::TypeScript | Language::JavaScript => true,
197	        Language::Rust | Language::Python => false,
198	    }
199	}
