1	//! The `monokl` command line: parses arguments, runs a command and prints agent-facing output.
2	//!
3	//! This is the agent layer. It budgets a core result and renders it with michi; core never prints.
4	
5	use std::ffi::OsString;
6	use std::io::Write;
7	use std::process::ExitCode;
8	use std::sync::Arc;
9	
10	use camino::Utf8PathBuf;
11	use clap::{Args, Parser, Subcommand};
12	
13	use crate::analysis::registry::AnalyzerRegistry;
14	use crate::budget::{Budget, apply_budget};
15	use crate::error::MonoklError;
16	use crate::output::agent::{ErrorContext, ToDomainError, render_projection};
17	use crate::pipeline::{SearchRequest, search};
18	use crate::text_search::DEFAULT_MAX_FILES;
19	use crate::types::{Diagnostic, DiagnosticKind, Language};
20	
21	/// AST-aware code search for coding agents.
22	#[derive(Debug, Parser)]
23	#[command(name = "monokl", version, about)]
24	struct Cli {
25	    #[command(subcommand)]
26	    command: Command,
27	}
28	
29	#[derive(Debug, Subcommand)]
30	enum Command {
31	    /// Searches a directory and prints the matching code blocks, best first.
32	    Search(SearchArgs),
33	}
34	
35	#[derive(Debug, Args)]
36	struct SearchArgs {
37	    /// The query: words, "quoted phrases", `+required`, `-excluded` and `regex:pattern` terms.
38	    query: String,
39	    /// The directory to search.
40	    #[arg(default_value = ".")]
41	    path: Utf8PathBuf,
42	    /// Treats the whole query as one literal term.
43	    #[arg(long)]
44	    exact: bool,
45	    /// Searches test files too.
46	    #[arg(long)]
47	    tests: bool,
48	    /// Searches hidden files and files that .gitignore or .ignore would exclude.
49	    #[arg(long)]
50	    no_ignore: bool,
51	    /// Searches only this language.
52	    #[arg(long, value_enum)]
53	    language: Option<Language>,
54	    /// The most results to print.
55	    #[arg(long, default_value_t = Budget::default().max_results)]
56	    max_results: usize,
57	    /// The most tokens of code to print.
58	    #[arg(long, default_value_t = Budget::default().max_tokens)]
59	    max_tokens: usize,
60	    /// The most bytes of code to print.
61	    #[arg(long, default_value_t = Budget::default().max_bytes)]
62	    max_bytes: usize,
63	}
64	
65	/// Runs the command line with `args`, writing results to `out` and errors to `err`.
66	///
67	/// Returns success when the command ran, even if it found nothing; failure for any error.
68	#[must_use]
69	pub fn run<I, T>(args: I, out: &mut impl Write, err: &mut impl Write) -> ExitCode
70	where
71	    I: IntoIterator<Item = T>,
72	    T: Into<OsString> + Clone,
73	{
74	    let cli = match Cli::try_parse_from(args) {
75	        Ok(cli) => cli,
76	        Err(e) => {
77	            // clap renders help and version on stdout and usage errors on stderr, with its own exit codes.
78	            let code = e.exit_code();
79	            let target: &mut dyn Write = if e.use_stderr() { err } else { out };
80	            let _written = write!(target, "{e}");
81	            return ExitCode::from(u8::try_from(code).unwrap_or(2));
82	        }
83	    };
84	    let Command::Search(args) = cli.command;
85	    match run_search(&args) {
86	        Ok(text) => {
87	            let _written = writeln!(out, "{text}");
88	            ExitCode::SUCCESS
89	        }
90	        Err(text) => {
91	            let _written = writeln!(err, "{text}");
92	            ExitCode::FAILURE
93	        }
94	    }
95	}
96	
97	fn registry() -> AnalyzerRegistry {
98	    #[cfg(feature = "lang-ts")]
99	    let analyzers: Vec<Arc<dyn crate::analysis::LanguageAnalyzer>> =
100	        vec![Arc::new(crate::analysis::ts::TsAnalyzer::new())];
101	    #[cfg(not(feature = "lang-ts"))]
102	    let analyzers: Vec<Arc<dyn crate::analysis::LanguageAnalyzer>> = Vec::new();
103	    AnalyzerRegistry::new(analyzers)
104	}
105	
106	fn run_search(args: &SearchArgs) -> Result<String, String> {
107	    let request = SearchRequest {
108	        root: &args.path,
109	        query: &args.query,
110	        exact: args.exact,
111	        allow_tests: args.tests,
112	        respect_ignore_files: !args.no_ignore,
113	        language: args.language,
114	    };
115	    let result = search(&registry(), &request).map_err(|e| error_text(&e))?;
116	
117	    let mut ranked = result.ranked;
118	    let mut diagnostics = result.diagnostics;
119	    // Paths print relative to the working directory when they are under it, so every row spends fewer tokens.
120	    if let Some(cwd) = std::env::current_dir().ok().and_then(|dir| Utf8PathBuf::from_path_buf(dir).ok()) {
121	        for block in &mut ranked {
122	            relativize(&mut block.block.file, &cwd);
123	        }
124	        for diagnostic in &mut diagnostics {
125	            if let Some(path) = &mut diagnostic.path {
126	                relativize(path, &cwd);
127	            }
128	        }
129	    }
130	    if result.ceiling_hit {
131	        diagnostics.push(Diagnostic {
132	            kind: DiagnosticKind::Warning,
133	            path: None,
134	            message: format!(
135	                "{} files matched but hits were kept for only the first {DEFAULT_MAX_FILES}; narrow the query or path",
136	                result.files_total
137	            ),
138	        });
139	    }
140	    let budget = Budget { max_results: args.max_results, max_tokens: args.max_tokens, max_bytes: args.max_bytes };
141	    let total_before = ranked.len();
142	    let response = apply_budget(ranked, total_before, &budget, diagnostics);
143	    render_projection(&response).map_err(|e| e.render())
144	}
145	
146	fn relativize(path: &mut Utf8PathBuf, base: &Utf8PathBuf) {
147	    if let Ok(relative) = path.strip_prefix(base) {
148	        *path = relative.to_owned();
149	    }
150	}
151	
152	fn error_text(error: &MonoklError) -> String {
153	    error.to_domain_error(ErrorContext { command: "search" }).render()
154	}
