1	//! Black-box tests: run the built `monokl` binary against the `small-ts` fixture project.
2	#![allow(clippy::unwrap_used, clippy::expect_used, reason = "a failing assertion should panic in a test")]
3	
4	use std::path::PathBuf;
5	use std::process::{Command, Output};
6	
7	fn fixture() -> PathBuf {
8	    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/small-ts")
9	}
10	
11	/// Runs `monokl` with the fixture as the working directory, so printed paths are relative.
12	fn monokl(args: &[&str]) -> Output {
13	    Command::new(env!("CARGO_BIN_EXE_monokl")).args(args).current_dir(fixture()).output().unwrap()
14	}
15	
16	fn stdout(output: &Output) -> String {
17	    String::from_utf8(output.stdout.clone()).unwrap()
18	}
19	
20	fn stderr(output: &Output) -> String {
21	    String::from_utf8(output.stderr.clone()).unwrap()
22	}
23	
24	#[test]
25	fn search_prints_ranked_blocks_with_relative_paths() {
26	    let output = monokl(&["search", "format", "."]);
27	    assert!(output.status.success(), "stderr: {}", stderr(&output));
28	    let text = stdout(&output);
29	    let mut lines = text.lines();
30	    assert_eq!(lines.next(), Some("search[3]{file,lineStart,lineEnd,nodeKind,symbolSignature,rank,finalScore}:"));
31	    let first = lines.next().unwrap();
32	    assert!(
33	        first.starts_with(
34	            "  src/utils/format.ts,1,3,function,\"function formatCurrency(amount: number, currency: string = 'USD'): string\",1,"
35	        ),
36	        "got: {first}"
37	    );
38	    assert!(text.lines().all(|line| !line.contains("/Users/")), "paths should be relative: {text}");
39	}
40	
41	#[test]
42	fn search_is_deterministic() {
43	    assert_eq!(stdout(&monokl(&["search", "price", "."])), stdout(&monokl(&["search", "price", "."])));
44	}
